## 🔌 3. Cliente da API — `src/api.js`

> **Este é o arquivo que você vai mais mexer**, pois depende do formato exato da sua API. Fiz ele aceitando **3 formatos comuns** (GET com query, POST JSON e parâmetro alternativo). Os comentários indicam como trocar.

```js
import { settings } from './settings.js';

/**
 * ADAPTE AO CONTRATO DA SUA API ⚠️
 *
 * Formatos suportados (qualquer um funciona — só mude PATH e PARÂMETROS):
 *   • GET    /v1/extract?source=URL_encoded&token=...
 *   • POST   /v1/extract  { "source": "https://...", "token": "..." }
 *   • POST   /v1/documentos { "url": "https://..." }
 *
 * Resposta esperada (adapte os nomes dos campos se forem outros):
 *
 * {
 *   meta: {
 *     titulo: string,
 *     autor: string,
 *     paginas: number | null,
 *     urlOrigem: string,
 *     resumo: string,
 *   },
 *   secoes: [ { ordem: number, titulo: string, trecho: string } ],
 *   textoCompleto: string   // opcional; pode vir como contenido, body, texto_integral...
 * }
 */

const BASE = (settings.apiBase.replace(/\/+$/, '') + '/v1').trim();
const LIMITE_MS = (settings.processTimeoutSec || 300) * 1000;

export async function buscarLinkNaApi(urlPdf) {
  // ⚠️ Só mande parâmetros no formato da SUA API (query OU corpo JSON — nunca os dois juntos se ela só aceita um)
  const qs = new URLSearchParams();
  qs.set('source', encodeURIComponent(urlPdf)); // codifica espaços como %20 etc.
  qs.set('token', settings.apiKey ?? '');     // some essa linha se sua API usa Header: Authorization: Bearer ...

  const urlCompleta = `${BASE}/extract?${qs.toString()}`;

  const controlador = new AbortController();
  const timer = setTimeout(() => controlador.abort(), LIMITE_MS);

  try {
    const resposta = await fetch(urlCompleta, {
      method: 'GET',
      headers: {
        Accept: 'application/json',
        // Authorization: `Bearer ${settings.apiKey}`, // COMENTE SE NÃO USAR MAIS ESSA LINHA
      },
      signal: controlador.signal,
    });

    clearTimeout(timer);

    if (!resposta.ok) {
      const corpo = await resposta.text().catch(() => '');
      throw new Error(`A API respondeu ${resposta.status}: ${corpo.slice(0, 300)}`);
    }

    const dados = await resposta.json();
    validarForma(dados);
    return dados;
  } catch (erro) {
    if (erro.name === 'AbortError') {
      throw new Error(`Tempo esgotado (limite: ${settings.processTimeoutSec}s).`);
    }
    throw erro;
  }
}

/** Garante um formato mínimo aceitável, tolerando nomes de campos diferentes */
function validarForma(dados) {
  if (!dados || (typeof dados !== 'object' && dados === null)) {
    throw new Error('Resposta da API não é um JSON objeto válido.');
  }
  if (!Array.isArray(dados.secoes)) {
    console.warn('[API] Campo "secoes" ausente/inválido. Confira src/api.js e src/helpers.js.');
    // tenta capturar formatos alternativos comuns em outras APIs
    const fontes = [dados.itens, dados.resultados, dados.pontos, dados.contents];
    let alternativa = null;
    for (const f of fontes) {
      if (Array.isArray(f) && f.length && f[0] && typeof f[0] === 'object') {
        alternativa = f;
        break;
      }
    }
    if (alternativa) dados.secoes = alternativa;
  }
}
```

