import { escapar, limpar } from '../helpers.js';
import { settings } from '../settings.js';
import { Embed } from 'discord.js';

export default async function ajuda(interaction) {
  const menu = await gerarCardapas();
  await interaction.channel.postMessage(menu);
}

/** Monta um "cardápio" de cards com os comandos, cada um com ícone, exemplo e descrição */
export async function gerarCardapas() {
  const cards = [
    {
      icon: '📄',
      titulo: '🔬 Extrair PDF',
      exemplo: '/extrair-pdf `<link-do-pdf>`',
      modos: [
        '📝 **Resumo** — Apenas resumo e primeiros trechos.',
        '📑 **Todas as seções** — Cada seção em uma mensagem separada.',
        '📘 **Texto completo** — Todo o conteúdo (em partes, se preciso).',
      ],
      desc: 'Envie o endereço de um PDF e receba de volta, de forma organizada: título, autor, páginas, resumo e seções extraídas.',
      cor: settings.cores.documents,
    },
    {
      icon: '🛠️',
      titulo: 'ℹ️ Ajuda',
      exemplo: '/ajuda',
      modos: [],
      desc: 'Esta mesma lista, organizada para consulta rápida.',
      cor: settings.cores.help,
    },
    // adicione novos comandos aqui conforme criar
  ];

  const INVITE = 'https://discord.gg/NOME_DO_SEU_INVITE_AQUI'; // troque pelo invite permanente

  const abertura = '👋 Bem-vindo(a)! Esse é o cardápio dos comandos:\n\n';
  const campos = cards.map((cartao) => {
    const usos = `[${cartao.exemplo}](${INVITE})`;
    const corpo = [cartao.modos.join('\n'), '', cartao.desc].filter(Boolean).join('\n\n');
    return {
      name: `${cartao.icon} **${cartao.titulo}**`,
      value: escapar(limpa(usos)) + '\n\n' + escapar(limpa(corpo)),
      inline: false,
    };
  });

  const embed = new Embed()
    .setTitle('📘 **Comandos disponíveis**')
    .setDescription(abertura)
    .addFields(...campos)
    .setTimestamp()
    .setColor(settings.cores.menu)
    .setFooter({ text: 'Feito com 💙 usando Node.js + discord.js' });

  return embed;
}
