  // ------------------------------------------------------------------
  if (
    interaction.commandType === 'MessageCommand' &&
    !interaction.isReply() &&
    (interaction.isMessageInChannel() || interaction.isDirect())
  ) {
    await interaction.reply({ filter: true }); // "lá, estou aqui 👋"

    const handler = comandos[interaction.name];
    if (!handler) {
      await interaction.channel.send({
        content: '❌ Comando não encontrado. Use `/ajuda` para listar os comandos.',
        ephemeral: true,
      });
      return;
    }

    try {
      await handler(interaction);
    } catch (err) {
      console.error('[bot] Erro no comando com prefixo:', err);
      await interaction.channel.send({
        content: `❌ **Erro:** ${err.message || 'Algo deu errado.'}`,
        ephemeral: true,
      });
      return;
    }
  }
});

