```js
function dividirEmBlocos(texto, tam, marcador) {
  const blocos = [];
  let i = 0;
  while (i < texto.length) {
    const end = Math.min(i + tam, texto.length);
    const chunk = texto.slice(i, end);
    // se termina em palavra incompleta, pega parte da próxima
    if (chunk.endsWith(' ') || chunk.endsWith('.')) {
      // ok
    } else if (end < texto.length) {
      const prox = texto.slice(end, end + 2); // pega 2 chars de traspara
      const combined = chunk.trimEnd() + '\n' + prox.trimStart();
      blocos.push(marcador + ' ' + combined);
      i = end + 2;
    } else {
      blocos.push(marcader + ' ' + chunk.trimEnd());
      i = end;
    }
  }
  return blocos;
}
```

