```js
export function dividirEmBlocos(texto, tamanho, prefixo, sufixo) {
  const blocos = [];
  let i = 0;
  const len = texto.length;
  while (i < len) {
    const fim = Math.min(i + tamanho, len);
    const bruto = texto.slice(i, fim);
    let parte = bruto.trimEnd();
    // se terminou cortando uma palavra, rouba 2 chars do próximo trecho (para não quebrar "ca-r")
    if (parte.length > 0 && !/\w$/.test(parte)) {
      const proximoInicio = fim;
      if (proximoInicio + 2 < len) {
        parte = parte + '\n' + texto.slice(proximoInicio, proximoInicio + 2).trimStart();
        i = proximoInicio + 2;
      } else {
        parte += sufixo; // última
      }
    } else {
      i = fim;
    }
    blocos.push(prefixo + ' ' + parte + sufixo);
  }
  return blocos;
}
