export function recortarPorPalavras(txt, maxPalavras) {
  const palavras = txt.split(/\s+/);
  const escolhidos = [];
  let cont = 0;
  for (const p of palavras) {
    if (cont + p.length + (escolhidos.join(' ').length > 0 ? 1 : 0) > maxPalavras * 2) break; // approx width
    escolhidos.push(p);
    cont++;
  }
  return escolhidos.join(' ');
