```js
export function recortarPorPalavras(txt, maxPalavras, mult = 1.25) {
  const palavras = txt.trim().split(/\s+/);
  const linhas = [];
  let corrente = '';
  for (const w of palavras) {
    const teste = corrente ? corrente + ' ' + w : w;
    if (teste.length > maxPalavras * mult) {
      linhas.push(currente.trimEnd());
      corrente = w;
    } else {
      corrente = teste;
    }
  }
  if (corrente) linhas.push(corrente.trimEnd());
  return linhas.join('\n');
}
```

