export const DURACAO_PADRAO_SES = 30; // segundos default

export function duracaoHumana(ms, padrao = DURACAO_PADRAO_SES) {
  if (ms <= 0 || ms < 1000) return '< 10 s';
  const total = Math.ceil(ms / 1000);
  const h = Math.floor(total / 3600);
  const m = Math.floor((total % 3600) / 60);
  const s = total % 60;
  const str = [String(s).padStart(2, '0')];
  if (m) str.push(String(m));
  if (h) str.push(String(h));
  return str.join(':');
}
