export async function modoCompleto(interaction, texto, inicio) {
  const cana = interaction.channel;
  const limite = 1700;
  const totalChars = texto.length;
  const totalBlocos = Math.ceil(totalChars / limite);

  // banner
  await cana.send(
    `⏳ Enviando o **texto completo** de um documento com *${totalChars.toLocaleString()}* caracteres...\n`
  );

  for (let k = 0; k < totalBlocos; k++) {
    const beg = k * limite;
    let fim = Math.min(beg + limite, totalChars);
    const bloco = texto.slice(beg, fim);
    const marca = k < totalBlocos - 1 ? '\n❧ Continua…' : '';
