 *
 * Contratos suportados (todos funcionam igual — só troque o caminho):
 *
 * 1) GET /extrair?url=<codificado>&token=...
 * 2) POST /extrair { url: "...", token: "..." }
 * 3) POST /documentos/analisar { source: "https://..." }
 */
const BASE = (settings.apiBase.replace(/\/+$/, '') + '/v1').trim();
const LIMITE_MS = settings.processTimeoutSec * 1000;

export async function buscarLinkNaApi(urlPdf) {
  // 1) monta a URL com parâmetros (URLs com ? & são adicionadas automaticamente)
  let parametros = new URLSearchParams();
  parametros.set('source', encodeURIComponent(urlPdf)); // codifica %20 etc. Confirme se sua API espera encoded

  const full = `${BASE}/extrair?${parametros.toString()}`;

  const controlador = new AbortController();
  const timer = setTimeout(() => controlador.abort(), LIMITE_MS);

  try {
    const resposta = await fetch(full, {
      method: 'GET',
      headers: {
        Authorization: `Bearer ${settings.apiKey}`, // ou 'ApiKey ' ...
        Accept: 'application/json',
      },
      signal: controlador.signal,
    });

    clearTimeout(timer);

    if (!resposta.ok) {
      const textoErr = await resposta.text().catch(() => '');
      throw new Error(
        `A API respondeu ${resposta.status}: ${textoErr.slice(0, 300)}`
      );
    }

    const dados = await resposta.json();

    // Garante um formato mínimo razoável (caso a API traga dados bagunçados)
    validarResposta(dados);
    return dados;
  } catch (erro) {
    if (erro.name === 'AbortError') {
      throw new Error('Tempo esgotado: a API não respondeu em ' + settings.processTimeoutSec + 's.');
    }
    throw erro;
  }
}

function validarResposta(dados) {
  if (!dados || (typeof dados !== 'object' || dados === null)) {
    throw new Error('Resposta da API não é um objeto JSON válido.');
  }
  if (!Array.isArray(dados.secoes)) {
    console.warn(
      '[API] Campo "secoes" ausente/incompatível. Ajuste normalizarDados() em helpers.js.'
    );
    // Fallback para campos alternativos usados por algumas APIs
    const candidatos = ['itens', 'resultados', 'partes', 'conteudos'];
    let alternativa = dados.itens || dados.resultados || dados.pontos || [];
    if (alternativa.length && !Array.isArray(alternativa[0])) {
      // parece que cada elemento é um documento inteiro; pegamos o primeiro como "header"
      console.warn('[API] Elementos parecem ser documentos inteiros. Reorganizando...');
      const primeiro = Array.isArray(dados) && dados[0] ? dados[0] : dados;
      alternativa = [...(dados.secoes || []), primeiro];
    }
    dados.secoes = alternativa;
  }
}
