import { settings } from './settings.js';

/** Dorme `ms` milissegundos (usado entre partes de textos longos) */
export function dormir(ms) {
  return new Promise((r) => setTimeout(r, ms));
}

/** Duração em HH:MM:SS (humana) */
export function duracaoHumana(ms) {
  if (ms <= 0) return '—';
  const totalSeg = Math.ceil(ms / 1000);
  const h = Math.floor(totalSeg / 3600);
  const m = Math.floor((totalSeg % 3600) / 60);
  const s = totalSeg % 60;
  const arr = [String(s).padStart(2, '0')];
  if (m > 0) arr.push(String(m).padStart(2, '0'));
  if (h > 0) arr.push(String(h));
  return arr.join(':');
}

/** Escapa texto para virar valor seguro de embed field (markdown) */
export function escapar(txt) {
  return String(txt)
    .replace(/\\/g, '\\\\')
    .replace(/[*+_~`[\]]/g, c => '\\' + c)
    .replace(/\n/g, ' ');
}

/** Quebra um texto em linhas verticais respeitando nº de palavras (para usar em valores de campo) */
export function quebrarLinhas(txt, maxPalavrasPorLinha, fator = 1.25) {
  const palavras = txt.trim().split(/\s+/);
  const linhas = [];
  let corrente = '';
  for (const p of palavras) {
    const candidata = corrente ? corrente + ' ' + p : p;
    if ((corrente ? corrente.length + p.length : p.length) > maxPalavrasPorLinha * fator) {
      linhas.push(currente.trimEnd());
      corrente = p;
    } else {
      corrente = candidata;
    }
  }
  if (corrente) linhas.push(corrente.trimEnd());
  return linhas.join('\n');
}

/** Normaliza a resposta da API nas estruturas que usamos aqui */
export function normalizarDados(resposta) {
  const meta = (() => {
    const m = resposta.meta;
    if (!m) {
      // procura títulos escondidos em propriedades alternativas
      const chaves = Object.keys(m || {}).filter((k) =>
        typeof m[k] === 'string' && (k.toLowerCase().includes('titulo') || k.toLowerCase().includes('title')))
      );
      if (chaves.length) {
        const obj = { ...m };
        const chaveTitulo = chaves.find((k) => k.toLowerCase().includes('titulo'));
        if (obj[chaveTitulo] !== undefined) obj.titulo = obj[chaveTitulo];
        return obj;
      }
    }
    return m || {};
  })();

  const secoes = normalizarListasDeSecoes(resposta);

  return { meta: {
    titulo: meta.titulo || 'Sem título informado',
    autor: (meta.autor || meta.author || meta.autores || '').trim() || 'Autor não informado',
    paginas: meta.paginas != null || meta.páginas != null
      ? (Number(meta.paginas) || Number(meta.páginas) || null)
      : null,
    origem: (meta.url || meta.origem || meta.src || meta.link).trim() || '',
    resumo: (meta.resumo || meta.summary || meta.sintese || '').trim(),
  }, secoes };
}

function normalizarListasDeSecoes(resposta) {
  const fonte =
    resposta.secoes || resposta.itens || resposta.resultados || resposta.pontos || resposta.contents || [];
  return fonte
    .map((item, idx) => {
      const base = item || {};
      const texto = String((base.trecho || base.conteudo || base.texto || base.categoria || '')).trim();
      return {
        ordem: Number(base.ordem ?? base.index ?? base.n ?? idx + 1),
        titulo: String((base.titulo || base.nome || base.head)).trim(),
        trecho: texto,
      };
    })
    .filter((s) => s.titulo.length > 0);
}
