export function escapar(txt) {
  let s = String(txt)
    .replace(/\\/g, '\\\\')
    .replace(/\[/g, '\\[')
    .replace(/\]/g, '\\]')
    .replace(/\*+/g, '\\*')
    .replace(/\+/g, '\\+')   // plus usado para itálico inline
    .replace(/_/g, '\\_')
    .replace(/~)/g, '\\~')
    .replace(/`/g, '\\`');
  return s.replace(/\n/g, ' ');
