```js
import {
  normalizarDados,
  quebrarLinhas,
  escapar,
  limpar,
  dormir,
} from '../helpers.js';
import { buscarLinkNaApi, obterTextoCompleto } from '../api.js';
import { settings } from '../settings.js';

// Opções do comando (escolhas bonitas com emoji)
const ESCOLHAS_EXTRAIRO = [
  { id: 'resumo',   titulo: '📝 Resumo',       help: 'Só o resumo e os primeiros trechos.' },
  { id: 'todas',    titulo: '📑 Todas as seções', help: 'Cada seção em uma mensagem separada.' },
  { id: 'completo', titulo: '📘 Texto completo', help: 'Todo o conteúdo (dividido em partes se precisar).' },
];

export default async function extrairPdf(interaction) {
  // 1. argumentos
  const link = interaction.options.getString('link', true);
  if (!/^(?:https:\/\/|http:\/\/)[^/.]*\.pdf$/i.test(link)) {
    throw new ErroUso('Informe um link válido terminando em .pdf (ex.: https://exemplo.com/arquivo.pdf)');
  }
  const modo = interaction.options.getString('modo', 'resumo'); // definido pelas escolhas

  // 2. aviso de processamento
  const cana = interaction.channel;
  const aviso = modo === 'todas' ? '⏳ Enviando as seções uma a uma…' : '⏳ Processando o documento…';
  await cana.send(`⏳ ${aviso}\n📎 <${link}>`);

  // 3. chamada à API
  let dados;
  try {
    dados = await buscarLinkNaApi(link);
  } catch (err) {
    console.error('[extrair-pdf] Falha com a API:', err);
    await cana.send({ content: `❌ **Erro de conexão com a API:** ${err.message}`, ephemeral: true });
    throw err;
  }

  const agora = Date.now();

  // 4. normaliza a resposta da API
  const meta = normalizarDados(dados);
  const secoes = normalizarSecoesDaResposta(dados);
  const origem = ((dados.meta?.urlOrigem || dados.meta?.url || dados.url || dados.link || dados.source || '').trim()) || '';

  // 5. executa o modo
  if (modo === 'resumo')    await apresentar(resumo, interaction, cana, agora, meta, secoes, origem);
  if (modo === 'todas')     await apresentarSecoes(secoes, interaction, cana, origem, agora);
  if (modo === 'completo')  await apresentarTextoCompleto(dados, interaction, cana, agora, origem);
}

function normalizarSecoesDaResposta(resposta) {
  const fonte = resposta.secoes || resposta.itens || resposta.resultados || resposta.pontos || [];
  return fonte.map((it, i) => ({
    titulo: String((it.titulo || it.nome || it.head)).trim(),
    trecho: String((it.trecho || it.conteudo || it.texto)).trim(),
    ordem: i + 1,
  })).filter((s) => s.titulo.length > 0);
}

async function apresentar(resumoTipo, intAct, cana, inicio, meta, secoes, origem) {
  const fim = Date.now();
  const duracao = duracaoHumana(fim - inicio) || '—';

  const campos = [
    { name: '**📄 Título:**',       value: limpar(meta.titulo || '—'),   inline: true },
    { name: '**✍️ Autor:**',        value: limpar(meta.autor || '—'),   inline: true },
    { name: '**🖨️ Páginas:**',      value: meta.paginas ? `${meta.paginas} pág.` : '—', inline: true },
    { name: `**⏱️ Tempo:**`,        value: duracao,                      inline: true },
    { name: `**📄 Seções:**`,       value: `${secoes.length} · ~${palavrasTotais(secoes).toLocaleString()} palavras`, inline: true },
    { name: '**🔗 Origem (clique para abrir):**', value: linkCliavel(origem), inline: false },
  ];

  const resumoTexto = meta.resumo ? `\`\`\`markdown\n${limpar(quebrarLinhas(meta.resumo, 300))}\n\`\`\`` : '';

  const embed = new Discord.Embed()
    .setTitle(escapar(limpa(meta.titulo || '📄 Informações do PDF')))
    .setDescription(resumoTexto)
    .addFields(...campos, ...(secoes.slice(0, 8).map((s, i) => ({
      name: `**§${i + 1}. ${s.titulo}** (${palavrasTotais([s.trecho])} palavras)`,
      value: limpar(quebrarLinhas(s.trecho, 150)),
      inline: false,
    })))
    .setTimestamp()
    .setColor(settings.cores.documents)
    .setURL(origem);

  await cana.send(embed);
}

function palavrasTotais(arr) {
  return arr.reduce((s, x) => s + (x.trecho ? x.trecho.split(/\s+/).length : 0), 0);
}

function linkCliavel(url) {
  return url.includes('.') && !url.includes('#') ? `[${url}](${url})` : url;
}

async function apresentarSecoes(secoes, intAct, cana, origem, inicio) {
  const total = secoes.length;
  if (!total) {
    await cana.send({ content: '⚠️ Nenhuma seção disponível. Tentou extração? Use outro link.', ephemeral: true });
    return;
  }
  await cana.send(`⏳ Enviando **${total} seções** uma por uma…`);

  const msgs = [];
  for (let i = 0; i < total; i++) {
    const nPalavras = secoes[i].trecho ? secoes[i].trecho.split(/\s+/).length : 0;
    msgs.push(await cana.send(
      `➡️ **${i + 1}/${total} — ${secoes[i].titulo}** (${nPalavras} palavras)`
    ));
    if (i < total - 1) await dormir(500);
  }
  if (msgs.length) {
    await msgs[msgs.length - 1].edit({
      content: `✅ Concluído! Enviadas **${total} seções**.\n🔗 ${limpar(origem || '')}\n💡 Peça o resumo: \`/extrair-pdf <link> resumo\``,
    });
  }
}

async function apresentarTextoCompleto(dados, intAct, cana, inicio, origem) {
  const texto = obterTextoCompleto(dados);
  const limite = settings.maxFullTextPerMsg || 1700;
  const totalChars = texto.length || 0;
  const partes = totalChars > 0 ? Math.ceil(totalChars / limite) : 0;

  await cana.send(`⏳ Enviando o **texto completo** de um documento com *${totalChars.toLocaleString()}* caractere(s)…`);

  if (!texto) {
    await cana.send({ content: '⚠️ O texto integral não está disponível. Vou mostrar o resumo em vez disso.', ephemeral: true });
    await apresentarResumoFallback(intAct, cana, texto.length ? Date.now() - (totalChars||0) : new Date(), dados, origem);
    return;
  }

  let k = 0;
  while (k < partes) {
    const seg = texto.slice(k * limite, (k + 1) * limite);
    const marca = k < partes - 1 ? `\n❧ *(continua…)*` : '';
    const msg = `❧ **${k + 1} de ${partes}**\n${limpar(seg)}${marca}`.slice(0, 1850);
    await cana.send(msg);
    k += limite;
    if (k < partes) await dormir(300);
  }

  await cana.send(`✅ **Pronto!** Documento enviado (${partes} partes).\n📎 ${limpar(origem)}\n💡 Detalhes? Use \`/extrair-pdf <link> resumo\`.`);
}

