/**
 * ADAPTE ESTE BLOCO AO CONTRATO REAL DA SUA API ⚠️
 *
 * Exemplos típicos (qualquer um funciona — só mude PATH e PARÂMETROS):
 *
 *  • GET /v1/extract?source=URL%20codificada&key=...
 *  • POST /v1/extract { "source": "https://...", "key": "..." }
 *  • POST /v1/documentos { "url": "https://..." }
 *
 * Formato ESPERADO (ajuste os nomes dos campos se diferente):
 *
 * {
 *   meta: {
 *     titulo: string,
 *     autor: string,
 *     paginas: number | null,
 *     urlOrigem: string,
 *     resumo: string,
 *     ...
 *   },
 *   secoes: [ { ordem: number, titulo: string, trecho: string } ],
 *   textoCompleto: string (opcional, às vezes chamado de contenido/body/texto_integral)
 * }
 */
const BASE = (settings.apiBase.replace(/\/+$/, '') + '/v1').trim();
const LIMITE_MS = (settings.processTimeoutSec || 300) * 1000;

export async function buscarLinkNaApi(urlPdf) {
  const qs = new URLSearchParams();
  qs.set('source', encodeURIComponent(urlPdf)); // codifica espaços (%20) etc. Confirme com a doc da sua API se ela espera encoded ou cru
  qs.set('apiKey', settings.apiKey ?? ''); // algumas APIs pedem parâmetro separado (remova se sua API usa Header Authorization)

  const full = `${BASE}/extract?${qs.toString()}`;
  // se sua API NÃO for pública a CORS, ajuste o cabeçalho abaixo (ou passe por um proxy)

  const controlador = new AbortController();
  const timer = setTimeout(() => controlador.abort(), LIMITE_MS);

  try {
    const resposta = await fetch(full, {
      method: 'GET',
      headers: {
        Authorization: `Bearer ${settings.apiKey}`, // ou 'ApiKey ' + key, conforme sua API
        Accept: 'application/json',
      },
      signal: controlador.signal,
    });

    clearTimeout(timer);

    if (!resposta.ok) {
      const errTexto = await resposta.text().catch(() => '');
      throw new Error(`API ${resposta.status}: ${errTexto.slice(0, 300)}`);
    }

    const dados = await resposta.json();
    validarForma(dados);
    return dados;
  } catch (erro) {
    if (erro.name === 'AbortError') {
      throw new Error(`Tempo esgotado (limite: ${settings.processTimeoutSec}s).`);
    }
    throw erro;
  }
}

function validarForma(dados) {
  if (!dados || (typeof dados !== 'object' && dados !== null)) {
    throw new Error('Resposta da API inválida: esperava um JSON objeto.');
  }
  if (!Array.isArray(dados.secoes)) {
    console.warn('[API] Campo "secoes" ausente ou inválido. Ajuste src/api.js / helpers.js.');
    // tenta recuperar de alternativas usadas por outras APIs
    const fontes = [dados.itens, dados.resultados, dados.pontos, dados.contents];
    let alt = null;
    for (const f of fontes) {
      if (Array.isArray(f)) {
        alt = f[0] && typeof f[0] === 'object' ? f : [];
        break;
      }
    }
    if (alt) dados.secoes = alt;
  }
}
