import { Colors } from 'discord.js';
import { settings } from './settings.js';

/** Dorme ms milissegundos (usado pausar entre partes de texto longo) */
export function dormir(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/** Duração em HH:MM:SS a partir de milissegundos */
export function duracaoHumana(ms) {
  if (ms <= 0) return '—';
  const totalSeg = Math.ceil(ms / 1000);
  const h = Math.floor(totalSeg / 3600);
  const m = Math.floor((totalSeg % 3600) / 60);
  const s = totalSeg % 60;
  const partes = [String(s).padStart(2, '0')];
  if (m) partes.push(String(m).padStart(2, '0'));
  if (h) partes.push(String(h));
  return partes.join(':');
}

/** Escapa caracteres que atrapalhariam o markdown de embeds */
export function escapar(txt) {
  let s = String(txt).replace(/\\/g, '\\\\'); // primeira prioridade: barras invertidas
  s = s.replace(/[*+_~`[\]]/g, (char) => '\\' + char);
  return s.replace(/\n/g, ' ');
}

/** Limpa/remova quebras de linha (para campos e títulos de embed) */
export function limpar(txt) {
  return String(txt).replace(/\n/g, ' ');
}

/** Quebra texto em linhas respeitando limite de palavras (bom para valores de campo) */
export function quebrarLinhas(txt, maxPalavrasPorLinha, fator = 1.25) {
  const palavras = txt.trim().split(/\s+/);
  const linhas = [];
  let corrente = '';
  for (const palavra of palavras) {
    const tent = corrente ? corrente + ' ' + palavra : palavra;
    const comprimento = (corrente ? corrente.length : 0) + palavra.length;
    if (comprimento > maxPalavrasPorLinha * fator) {
      linhas.push(currente.trimEnd());
      corrente = palavra;
    } else {
      corrente = tent;
    }
  }
  if (corrente) linhas.push(corrente.trimEnd());
  return linhas.join('\n');
}

/** Contagem de palavras de um trecho de texto */
export function totalPalavras(trecho) {
  return trecho ? trecho.split(/\s+/).length : 0;
}

/**
 * NORMALIZA A RESPOSTA DA API para nosso formato interno.
 * ⚠️ Adapte ao formato REAL da sua API: seus nomes de campos podem diferir.
 * Abaixo tratamos variações comuns: { meta:{...} } ou raiz direta.
 */
export function normalizarDados(resposta) {
  const meta = (() => {
    const m = resposta.meta;
    if (!m) return {};
    const extras = { ...m };
    // campos alternativos possíveis (comente/remova se não existirem na sua API)
    if (extras.titulo !== undefined) extras.titulo = extras.titulo;
    if (extras.autores && Array.isArray(extras.autores)) extras.autor = extras.autores[0];
    if (extras.nome_documento !== undefined) extras.titulo = extras.nome_documento;
    return extras;
  })();

  const secoes = normalizarSecoes(resposta);

  return {
    meta: {
      titulo: limpar(meta.titulo || 'Sem título informado'),
      autor: limpar(String(meta.autor || 'Autor não informado')),
      paginas: Number(meta.paginas) != null || Number(meta.páginas) != null ? (Number(meta.paginas) || Number(meta.páginas)) : null,
      origem: limpar(String((meta.url || meta.origem || meta.link || meta.src || '').trim())),
      resumo: limpar(String((meta.resumo || meta.summary || '').trim())),
    },
    secoes,
  };
}
