async function enviarTextoIntegral(dados, intAct, cana, inicio, origem) {
  const texto = obterTextoCompleto(dados);
  const limite = settings.maxFullTextPerMsg || 1700;
  const totalChars = texto.length;
  const totalPartes = totalChars > 0 ? Math.max(1, Math.ceil(totalChars / limite)) : 0;

  if (!texto) {
    await cana.send({
      content: '⚠️ A API não retornou o texto integral. Vou mostrar o **resumo** em vez disso.',
      ephemeral: true,
    });
    // Fallback automático: mostra resumo
    const { normalizarDados: nd } = await import('../helpers.js');
    await ND_RESUMO(intAct, cana, totalChars ? Date.now() - 0 : new Date(), dados, origem);
    return;
  }

  await cana.send(`⏳ Enviando **${totalPartes} parte(s)** do texto completo (${totalChars.toLocaleString()} caractere(s))…`);

  let k = 0;
  while (k < totalPartes) {
    const ini = k * limite;
    const fim = Math.min(ini + limite, totalChars);
    const bloco = texto.slice(ini, fim);
    const sufixo = k < totalPartes - 1 ? `\n❧ *(continua…)*` : '';
    const mensagem = `❧ **Parte ${k + 1} de ${totalPartes}**\n${escapar(limpa(bloco))}${sufixo}`.slice(0, 1850);

    await cana.send(mensagem);
    k += limite;
    if (k < totalPartes) await dormir(300);
  }

  await cana.send(`✅ **Concluído!**\n📄 Total: ${totalChars.toLocaleString()} caracteres · ${totalPartes} partes.\n🔗 ${limpar(origem)}`);
}
