      return;
    }

    try {
      await handler(interaction);
    } catch (err) {
      console.error('[bot] Erro no comando', err);
      await interaction.editReply({
        content: `❌ **Erro:** ${err.message || 'Algo inesperado aconteceu.'}`,
        ephemeral: true,
