```js
import { Colors } from 'discord.js';
import { settings } from './settings.js';

/** Pausa síncrona de ms milissegundos (retorna um Promise) */
export function dormir(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/** Formata um intervalo em HH:MM:SS (ou "—") */
export function duracaoHumana(ms) {
  if (ms <= 0) return '—';
  const totalSeg = Math.ceil(ms / 1000);
  const h = Math.floor(totalSeg / 3600);
  const m = Math.floor((totalSeg % 3600) / 60);
  const s = totalSeg % 60;
  const partes = [String(s).padStart(2, '0')];
  if (m) partes.push(String(m).padStart(2, '0'));
  if (h) partes.push(String(h));
  return partes.join(':');
}

/** Escapa texto para uso seguro como valor de campo/título de embed */
export function escapar(txt) {
  let s = String(txt).replace(/\\/g, '\\\\');
  s = s.replace(/[*+_~`[\]]/g, (c) => '\\' + c);
  return s.replace(/\n/g, ' ');
}

/** Remove quebras de linha */
export function limpar(txt) {
  return String(txt).replace(/\n/g, ' ');
}

/** Quebra texto em linhas respeitando o limite de palavras (bom para trechos de seções) */
export function quebrarLinhas(txt, maxPalavras, fator = 1.25) {
  const palavras = txt.trim().split(/\s+/);
  const linhas = [];
  let corrente = '';
  for (const palavra of palavras) {
    const candidato = corrente ? corrente + ' ' + palavra : palavra;
    if ((corrente ? corrente.length : 0) + palavra.length > maxPalavras * fator) {
      linhas.push(currente.trimEnd());
      corrente = palavra;
    } else {
      corrente = candidato;
    }
  }
  if (corrente) linhas.push(corrente.trimEnd());
  return linhas.join('\n');
}

export function totalPalavras(trecho) {
  return trecho ? trecho.split(/\s+/).length : 0;
}

/**
 * Transforma a resposta da API no formato que nossos handlers esperam.
 * ⚠️ Se sua API usar nomes de campos diferentes, ajuste os pontos marcados.
 */
export function normalizarDados(resposta) {
  // --- metadados ---
  const meta = (() => {
    const m = resposta.meta;
    if (!m) return {};
    const extras = { ...m };
    if (extras.titulos) { extras.titulo = Array.isArray(extras.titulos) ? extras.titulos[0] : extras.titulos; }
    if (extras.autores && Array.isArray(extras.autores)) extras.autor = extras.autores.join(' ');
    if (extras.nome_do_documento || extras.documento) extras.titulo = extras.nome_do_documento || extras.documento;
    return extras;
  })();

  // --- seções ---
  const secoes = normalizarSecoes(resposta);

  return {
    meta: {
      titulo: limpar(meta.titulo || 'Sem título'),
      autor: Array.isArray(meta.autor)
        ? limpar(meta.autor.join(' '))
        : limpar(String(meta.autor || 'Autor não informado')),
      paginas: meta.paginas != null && meta.paginas != undefined
        ? Number(meta.paginas)
        : null,
      origem: limpar(String((meta.url || meta.origem || meta.link || '').trim())),
      resumo: limpar(String((meta.resumo || meta.summary || '').trim())),
    },
    secoes,
  };
}

/** Mesclando formatos: { secoes:[...] } ou { itens:[...] }, etc. */
export function normalizarSecoes(resposta) {
  const fonte =
    resposta.secoes || resposta.itens || resposta.resultados || resposta.pontos || resposta.contents || [];

  return fonte
    .map((item, idx) => {
      const base = item || {};
      return {
        ordem: idx + 1,
        titulo: String((base.titulo || base.nome || base.head || base.categoria || '')).trim(),
        trecho: String((base.trecho || base.conteudo || base.texto || base.paragrafo || '')).trim(),
      };
    })
    .filter((s) => s.titulo.length > 0);
}
```

