    : 'Resumo indisponível nesta extração.';

  const extras = secoes.length > 8
    ? `\n\n📂 Existe(m) mais **${secoes.length - 8} seção(ões)** — peça todas com \`/extrair-pdf <link> todas\`.`
    : '';

